sys_variable_value.value:
(function execute(inputs, outputs) {
var grRecord = new GlideRecord(inputs.recordTable);
grRecord.addQuery('sys_id', inputs.recordId );
grRecord.query();

if(grRecord.next()){
    grRecord.state = 	14;
    grRecord.update();
}

outputs["updatedrecord1"] = grRecord.sys_id;

})(inputs, outputs);

